import{_ as o,o as r,c as a,a2 as s}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Estado del servicio","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/service-status.md","filePath":"es-ES/user-guide/settings/service-status.md","lastUpdated":1787586465000}'),i={name:"es-ES/user-guide/settings/service-status.md"};function t(n,e,d,l,c,u){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="estado-del-servicio" tabindex="-1">Estado del servicio <a class="header-anchor" href="#estado-del-servicio" aria-label="Permalink to &quot;Estado del servicio&quot;">​</a></h1><p>La página de Estado del servicio supervisa la salud del servicio de indexación en segundo plano de Lertaro e integra visores de registro en tiempo real para los procesos Service, App y Hook. La página se encuentra en <strong>Configuración → Estado del servicio</strong>.</p><h2 id="_1-control-y-estado-del-servicio" tabindex="-1">1. Control y estado del servicio <a class="header-anchor" href="#_1-control-y-estado-del-servicio" aria-label="Permalink to &quot;1. Control y estado del servicio&quot;">​</a></h2><p>La tarjeta superior muestra el estado del servicio de Windows con privilegios elevados:</p><ul><li><strong>Indicadores de estado</strong>: <ul><li><strong>Listo (Ready)</strong>: El servicio funciona correctamente y muestra el recuento de archivos y carpetas indexados.</li><li><strong>Indexando (Indexing)</strong>: Escaneo inicial o reconstrucción en curso (con indicador animado).</li><li><strong>Instalando (Installing)</strong>: Registro y arranque del servicio de Windows.</li><li><strong>Error</strong>: El servicio no responde o ha fallado (con distintivo de advertencia y descripción).</li></ul></li><li><strong>Autorrecuperación e instalación</strong>: El botón <strong>Instalar e iniciar servicio</strong> aparece únicamente si el servicio no está instalado o se encuentra en estado de error. En funcionamiento normal, permanece siempre en segundo plano.</li></ul><h2 id="_2-visor-de-registros-en-vivo-para-tres-procesos" tabindex="-1">2. Visor de registros en vivo para tres procesos <a class="header-anchor" href="#_2-visor-de-registros-en-vivo-para-tres-procesos" aria-label="Permalink to &quot;2. Visor de registros en vivo para tres procesos&quot;">​</a></h2><p>La consola inferior está dividida en tres pestañas que corresponden a los procesos de Lertaro:</p><ul><li><strong>Pestaña App</strong>: Registros de la interfaz de usuario WPF, interacción de búsqueda y atajos.</li><li><strong>Pestaña Hook</strong>: Eventos del proceso de interceptación de teclado de bajo nivel (<code>Lertaro.Hook.exe</code>).</li><li><strong>Pestaña Service</strong>: Procesamiento del diario USN, escaneo de disco, árbol en memoria y comunicaciones IPC del servicio (<code>Lertaro.Service.exe</code>).</li></ul><h3 id="filtrado-y-mantenimiento" tabindex="-1">Filtrado y mantenimiento <a class="header-anchor" href="#filtrado-y-mantenimiento" aria-label="Permalink to &quot;Filtrado y mantenimiento&quot;">​</a></h3><ul><li><strong>Filtro por nivel</strong>: Permite seleccionar &quot;Todos / Error / Advertencia / Información / Depuración&quot; con líneas coloreadas.</li><li><strong>Búsqueda en tiempo real</strong>: Filtra líneas de registro mediante palabras clave.</li><li><strong>Limpieza segura</strong>: Pulsa <strong>Borrar registros</strong> para vaciar la pestaña activa. Los registros del servicio se truncan de forma segura a través de IPC.</li></ul>',10)])])}const v=o(i,[["render",t]]);export{g as __pageData,v as default};
